MARKER = "BORIS AGENT GATEWAY"
PATCH = """
# ---- {marker} ---------------------------------------------------
try:
    from app.ext_api.router import router as _gateway_router
    app.include_router(_gateway_router)
    from app.ext_api.orchestrator import start_inline_runner as _gw_runner
    _gw_runner()
except Exception as _gateway_err:  # прод не должен падать из-за шлюза агентов
    import logging as _lg
    _lg.getLogger("uvicorn.error").error("agent gateway not loaded: %s", _gateway_err)
# ---- /{marker} --------------------------------------------------
""".format(marker=MARKER)


def backend_dir():
    here = os.getcwd()
    if os.path.exists(os.path.join(here, "app", "main.py")):
        return here
    if os.path.exists("/root/BORIS/backend/app/main.py"):
        return "/root/BORIS/backend"
    sys.exit("не нашёл backend с app/main.py — запустите из /root/BORIS/backend")


def load_env_url(backend):
    url = os.environ.get("DATABASE_URL")
    if url:
        return url
    p = os.path.join(backend, ".env")
    if os.path.exists(p):
        for line in open(p, encoding="utf-8", errors="ignore"):
            if line.strip().startswith("DATABASE_URL="):
                return line.strip().split("=", 1)[1].strip().strip('"').strip("'")
    return None


def engine_for(url):
    from sqlalchemy import create_engine
    return create_engine(url, pool_pre_ping=True)


def say(step, text, ok=None):
    mark = "  " if ok is None else ("OK   " if ok else "FAIL ")
    print(f"  {mark}{step:<12} {text}")


# ------------------------------------------------------------------- recon

def cmd_recon(a):
    backend = backend_dir()
    print(f"\n  backend: {backend}")
    main_py = os.path.join(backend, "app", "main.py")
    src = open(main_py, encoding="utf-8").read()
    print(f"  app/main.py: {len(src)} байт, include_router встречается "
          f"{src.count('include_router(')} раз")
    print(f"  уже пропатчен: {'ДА' if MARKER in src else 'нет'}")
    pkg = os.path.join(backend, "app", "ext_api")
    print(f"  пакет app/ext_api: {'есть' if os.path.exists(pkg) else 'нет'}")

    conflicts = [l.strip() for l in src.split("\n") if "/api/v1" in l]
    print(f"  упоминания /api/v1 в main.py: {len(conflicts)}"
          + ("  <-- проверьте на конфликт префикса" if conflicts else ""))

    url = load_env_url(backend)
    print(f"  DATABASE_URL: {'найден' if url else 'НЕ НАЙДЕН'}")
    if not url:
        return
    from sqlalchemy import text
    with engine_for(url).begin() as c:
        for t in ("accounts", "campaigns", "campaign_items", "ext_api_keys", "ext_jobs",
                  "ext_audit", "ext_handoffs", "ext_agent_state", "ext_idempotency",
                  "ext_job_attempts"):
            n = c.execute(text("SELECT COUNT(*) FROM information_schema.tables "
                               "WHERE table_name=:t"), {"t": t}).scalar()
            if n:
                cnt = c.execute(text(f"SELECT COUNT(*) FROM {t}")).scalar()
                print(f"    таблица {t:<20} есть, строк: {cnt}")
            else:
                print(f"    таблица {t:<20} НЕТ (создам)")
        for t in ("accounts", "campaigns", "campaign_items"):
            cols = [r[0] for r in c.execute(text(
                "SELECT column_name FROM information_schema.columns "
                "WHERE table_name=:t ORDER BY ordinal_position"), {"t": t})]
            if cols:
                print(f"    {t}: {', '.join(cols)}")
    print()


# ------------------------------------------------------------------ install

def write_package(backend, apply):
    pkg = os.path.join(backend, "app", "ext_api")
    if apply:
        os.makedirs(pkg, exist_ok=True)
    for name, b64 in FILES.items():
        data = base64.b64decode(b64)
        path = os.path.join(pkg, name)
        state = "перезапишу" if os.path.exists(path) else "создам"
        print(f"      {state:<12} app/ext_api/{name}  ({len(data)} байт)")
        if apply:
            open(path, "wb").write(data)
    return pkg


def run_ddl(backend, apply):
    url = load_env_url(backend)
    if not url:
        sys.exit("DATABASE_URL не найден — DDL не выполнен")
    sql = base64.b64decode(FILES["ddl.sql"]).decode()
    def _has_body(chunk):
        # «;» внутри комментария рвёт файл на куски: кусок из одних комментариев
        # psycopg2 считает пустым запросом и падает. Такие куски пропускаем.
        return any(l.strip() and not l.strip().startswith("--")
                   for l in chunk.split("\n"))
    stmts = [s.strip() for s in sql.split(";") if s.strip() and _has_body(s)]
    print(f"      {len(stmts)} операций: CREATE IF NOT EXISTS и ADD COLUMN IF NOT EXISTS, "
          f"существующие данные не трогаются")
    if not apply:
        return
    from sqlalchemy import text
    with engine_for(url).begin() as c:
        for s in stmts:
            c.execute(text(s))


def patch_main(backend, apply):
    main_py = os.path.join(backend, "app", "main.py")
    src = open(main_py, encoding="utf-8").read()
    if MARKER in src:
        print("      app/main.py уже содержит блок шлюза — пропускаю")
        return None
    lines = src.split("\n")
    idx = None
    for i, ln in enumerate(lines):
        if ".include_router(" in ln:
            idx = i
    if idx is not None:
        depth = 0
        for j in range(idx, len(lines)):
            depth += lines[j].count("(") - lines[j].count(")")
            if depth <= 0:
                idx = j
                break
        where = f"после последнего include_router (строка {idx + 1})"
    else:
        for i, ln in enumerate(lines):
            if ln.startswith("if __name__"):
                idx, where = i - 1, f"перед блоком __main__ (строка {i + 1})"
                break
        else:
            idx, where = len(lines) - 1, "в конец файла"
    print(f"      вставка {where}")
    if not apply:
        return None
    stamp = time.strftime("%Y%m%d_%H%M%S")
    bak = f"{main_py}.before_gateway_{stamp}"
    open(bak, "w", encoding="utf-8").write(src)
    print(f"      бэкап: {os.path.basename(bak)}")
    open(main_py, "w", encoding="utf-8").write(
        "\n".join(lines[:idx + 1]) + "\n" + PATCH + "\n".join(lines[idx + 1:]))
    return bak


def compile_check(backend):
    r = subprocess.run([sys.executable, "-m", "compileall", "-q",
                        os.path.join(backend, "app", "ext_api")],
                       capture_output=True, text=True)
    return r.returncode == 0, (r.stderr or r.stdout).strip()[:400]


def import_check(backend):
    for mod in ("app.ext_api.db", "app.ext_api.errors", "app.ext_api.auth",
                "app.ext_api.registry", "app.ext_api.orchestrator", "app.ext_api.agents",
                "app.ext_api.health", "app.ext_api.router", "app.main"):
        r = subprocess.run([sys.executable, "-c", f"import {mod}"], cwd=backend,
                           capture_output=True, text=True,
                           env={**os.environ, "EXT_API_INLINE_RUNNER": "0"})
        if r.returncode != 0:
            return False, f"{mod}: " + (r.stderr.strip().splitlines() or ["?"])[-1]
    return True, "все модули импортируются"


def route_check(backend):
    r = subprocess.run([sys.executable, "-c",
                        "from app.main import app;"
                        "print(' '.join(sorted({getattr(x,'path','') for x in app.routes "
                        "if str(getattr(x,'path','')).startswith('/api/v1')})))"],
                       cwd=backend, capture_output=True, text=True,
                       env={**os.environ, "EXT_API_INLINE_RUNNER": "0"})
    paths = (r.stdout or "").split()
    need = {"/api/v1/commands", "/api/v1/capabilities", "/api/v1/health/production",
            "/api/v1/jobs/{job_id}", "/api/v1/handoffs", "/api/v1/agents",
            "/api/v1/dev/jobs", "/api/v1/dev/queue", "/api/v1/costs/approvals",
            "/api/v1/agents/adapters", "/api/v1/dev/board"}
    missing = need - set(paths)
    return (not missing), (f"маршрутов: {len(paths)}" if not missing
                           else "не поднялись: " + ", ".join(sorted(missing)))


def tests_check(backend, account):
    if not account:
        return None, "пропущены: не передан --account (без него нельзя тронуть боевые данные)"
    r = subprocess.run([sys.executable, "-m", "app.ext_api.selftest", "--account", account],
                       cwd=backend, capture_output=True, text=True,
                       env={**os.environ, "EXT_API_ALLOW_TEST_HOOKS": "1",
                            "EXT_API_INLINE_RUNNER": "0"})
    tail = [l for l in r.stdout.split("\n") if "ИТОГ" in l or l.strip().startswith("- ")]
    return r.returncode == 0, " | ".join(tail)[:600] or (r.stderr or "")[-400:]


def rollback(backend, bak):
    main_py = os.path.join(backend, "app", "main.py")
    if bak and os.path.exists(bak):
        shutil.copyfile(bak, main_py)
        print(f"\n  ОТКАТ: app/main.py восстановлен из {os.path.basename(bak)}")
    else:
        src = open(main_py, encoding="utf-8").read()
        if MARKER in src:
            a = src.index(f"# ---- {MARKER}")
            b = src.index(f"# ---- /{MARKER}") + len(f"# ---- /{MARKER}")
            b = src.index("\n", b) + 1
            open(main_py, "w", encoding="utf-8").write(src[:a] + src[b:])
            print("\n  ОТКАТ: блок шлюза вырезан из app/main.py")
    print("  Таблицы ext_* НЕ удалены — они ничего не ломают и хранят историю.")


# Наряды берутся через FOR UPDATE SKIP LOCKED, поэтому несколько исполнителей
# безопасны: один и тот же наряд двоим не достанется. Ревьюер один — приёмка
# идёт по подписке, и параллелить её значит упереться в лимиты.
# Пять потоков: столько же, сколько планировщик считает безопасным на
# этом железе. Меньше процессов — простаивающие слоты, больше —
# очередь внутри самих служб без выигрыша.
EXECUTOR_WORKERS = int(os.environ.get("BORIS_EXECUTOR_WORKERS", "8"))
UNITS = ([(f"boris-executor{'' if i == 1 else '-' + str(i)}", "app.ext_api.executor",
           f"BORIS executor #{i} (GPT as a server process)")
          for i in range(1, EXECUTOR_WORKERS + 1)] +
         [("boris-lead", "app.ext_api.lead", "BORIS lead (Claude review as a server process)")])
