DEPLOY_UNIT = """[Unit]
Description=BORIS: автоматическая выкатка принятых правок
After=network-online.target postgresql.service
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory={backend}
Environment=PYTHONUNBUFFERED=1
ExecStart={backend}/venv/bin/python3 -m app.ext_api.deploy run --idle 60
Restart=always
RestartSec=15
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
"""


def install_deploy(backend, apply):
    """Последний ручной шаг — выкатка — закрывается службой."""
    path = "/etc/systemd/system/boris-deploy.service"
    body = DEPLOY_UNIT.format(backend=backend)
    exists = os.path.exists(path)
    same = exists and open(path, encoding="utf-8").read() == body
    print(f"      {'уже настроена' if same else ('обновлю' if exists else 'создам')}  {path}")
    inbox = os.path.join(os.path.dirname(backend.rstrip('/')), "updates", "incoming")
    if apply:
        os.makedirs(inbox, exist_ok=True)
    print(f"      каталог обновлений: {inbox}")
    if not apply:
        return
    if not same:
        open(path, "w", encoding="utf-8").write(body)
        subprocess.run(["systemctl", "daemon-reload"], capture_output=True)
    subprocess.run(["systemctl", "enable", "boris-deploy"], capture_output=True)
    if os.environ.get("BORIS_DEPLOY_INSIDE") == "1":
        print("      служба boris-deploy не перезапускается: обновление идёт из неё самой")
    else:
        subprocess.run(["systemctl", "restart", "boris-deploy"], capture_output=True)
    time.sleep(2)
    r = subprocess.run(["systemctl", "is-active", "boris-deploy"],
                       capture_output=True, text=True)
    print(f"      служба boris-deploy: {(r.stdout or '').strip()}")


GITDEPLOY_UNIT = """[Unit]
Description=BORIS: транспорт обновлений из Git
After=network-online.target postgresql.service
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory={backend}
Environment=PYTHONUNBUFFERED=1
ExecStart={backend}/venv/bin/python3 -m app.ext_api.gitdeploy run --idle 120
Restart=always
RestartSec=30
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
"""


def install_gitdeploy(backend, apply):
    """Транспорт обновлений. Без адреса репозитория служба просто ждёт."""
    path = "/etc/systemd/system/boris-gitdeploy.service"
    body = GITDEPLOY_UNIT.format(backend=backend)
    exists = os.path.exists(path)
    same = exists and open(path, encoding="utf-8").read() == body
    print(f"      {'уже настроена' if same else ('обновлю' if exists else 'создам')}  {path}")
    if not apply:
        return
    if not same:
        open(path, "w", encoding="utf-8").write(body)
        subprocess.run(["systemctl", "daemon-reload"], capture_output=True)
    subprocess.run(["systemctl", "enable", "boris-gitdeploy"], capture_output=True)
    if os.environ.get("BORIS_DEPLOY_INSIDE") == "1":
        print("      служба boris-gitdeploy не перезапускается: обновление идёт из неё самой")
    else:
        subprocess.run(["systemctl", "restart", "boris-gitdeploy"], capture_output=True)
    time.sleep(2)
    r = subprocess.run(["systemctl", "is-active", "boris-gitdeploy"],
                       capture_output=True, text=True)
    print(f"      служба boris-gitdeploy: {(r.stdout or '').strip()}")
    code = ("import sys,json;sys.path.insert(0,'.');"
            "from app.ext_api import gitdeploy as g;"
            "res=g.ensure_transport();"
            "print('      AUTONOMOUS_GIT_TRANSPORT = ' + res['AUTONOMOUS_GIT_TRANSPORT']);"
            "print('      подключение: ' + str(res['connect'].get('url') or "
            "res['connect'].get('verdict') or ''));"
            "print('      круговая проверка: ' + str((res.get('roundtrip') or {})"
            ".get('ok')));"
            "print('      нужно от владельца: ' + res['action']) if res.get('action') "
            "else None;"
            "r=g.readiness();d=r['discovery'];"
            "print('      AUTONOMOUS_GIT_TRANSPORT = ' + r['status']);"
            "[print('        не хватает: ' + b) for b in r['blocked_by']];"
            "print('        вердикт: ' + str(r.get('verdict'))) if r.get('verdict') "
            "else None;"
            "print('      найдено remote: ' + (', '.join(d['remotes']) or 'нет'));"
            "print('      следы репозитория в конфигурации: ' + "
            "(', '.join((d.get('candidates') or [])[:5]) or 'не найдены'));"
            "print('      ключи доступа: ' + (', '.join(d.get('ssh_keys_present') or []) "
            "or 'нет')) ")
    p = subprocess.run([os.path.join(backend, "venv", "bin", "python3"), "-c", code],
                       cwd=backend, capture_output=True, text=True)
    print((p.stdout or p.stderr or "").rstrip()[:800])


def install_inbox(backend, apply):
    """Задания из Telegram. Без отдельного бота служба просто ждёт и не шумит."""
    path = "/etc/systemd/system/boris-inbox.service"
