def cmd_browser_setup(a):
    """Ставит headless-браузер: без него «desktop PASS / mobile PASS» — фикция."""
    backend = backend_dir()
    py = os.path.join(backend, "venv", "bin", "python3")
    print("\n  БРАУЗЕР ДЛЯ RUNTIME QA\n")
    r = subprocess.run([py, "-m", "pip", "install", "-q", "playwright"],
                       cwd=backend, capture_output=True, text=True)
    print("      pip playwright:", "ok" if r.returncode == 0 else (r.stderr or "")[-400:])
    r2 = subprocess.run([py, "-m", "playwright", "install", "--with-deps", "chromium"],
                        cwd=backend, capture_output=True, text=True)
    if r2.returncode != 0:
        r2 = subprocess.run([py, "-m", "playwright", "install", "chromium"],
                            cwd=backend, capture_output=True, text=True)
    print("      chromium:", "ok" if r2.returncode == 0 else (r2.stderr or "")[-600:])
    chk = subprocess.run([py, "-c",
                          "from app.ext_api import ops; print(ops.browser_available())"],
                         cwd=backend, capture_output=True, text=True)
    print("      проверка:", (chk.stdout or chk.stderr or "").strip()[:300])
    print()


def cmd_verify(a):
    backend = backend_dir()
    ok, msg = import_check(backend); say("IMPORT", msg, ok)
    ok2, msg2 = route_check(backend); say("ROUTES", msg2, ok2)
    if a.account:
        ok3, msg3 = tests_check(backend, a.account); say("TESTS", msg3, ok3)
    print()


def cmd_rollback(a):
    backend = backend_dir()
    baks = sorted(glob.glob(os.path.join(backend, "app", "main.py.before_gateway_*")))
    rollback(backend, baks[-1] if baks else None)


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description="Установщик BORIS AI Agent Gateway")
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("recon").set_defaults(func=cmd_recon)
    p = sub.add_parser("install")
    p.add_argument("--apply", action="store_true")
    p.add_argument("--account", help="аккаунт для прогона автотестов, например antonybatono")
    p.set_defaults(func=cmd_install)
    p = sub.add_parser("verify"); p.add_argument("--account"); p.set_defaults(func=cmd_verify)
    sub.add_parser("claude-code").set_defaults(func=cmd_claude_code)
    sub.add_parser("browser-setup").set_defaults(func=cmd_browser_setup)
    c = sub.add_parser("clients"); c.add_argument("--status", action="store_true")
    c.set_defaults(func=cmd_clients)
    e = sub.add_parser("e2e"); e.add_argument("--keep", action="store_true")
    e.set_defaults(func=cmd_e2e)
    sub.add_parser("rollback").set_defaults(func=cmd_rollback)
    args = ap.parse_args()
    args.func(args)
